-- Import function
-- Uses Details' native API: ImportProfile(profileString, name)
function DOCUI.Profiles.Details:Import()
    if not C_AddOns.IsAddOnLoaded("Details") then
        return false, "Details is not installed or enabled."
    end

    local details = _G["Details"]
    if not details then
        return false, "Details global not found. Try /reload first."
    end

    -- Import the profile string under the given name
    local importOk, importErr = pcall(function()
        details:ImportProfile(self.importString, self.profileName)
    end)

    if not importOk then
        return false, "Failed to import: " .. tostring(importErr)
    end

    -- Apply the profile if it isn't already active
    pcall(function()
        if details:GetCurrentProfileName() ~= self.profileName then
            details:ApplyProfile(self.profileName)
        end
    end)

    return true, "Details profile 'DOCUI' imported successfully!"
end
